arguments.new_str:
namespace Warehouse;

public sealed class InventoryTracker
{
    private readonly Dictionary<string, Dictionary<string, int>> _warehouseStock = new();
    private const string DefaultWarehouse = "Main";
    private readonly int _reorderThreshold;

    public InventoryTracker(int reorderThreshold = 10)
    {
        if (reorderThreshold < 0)
            throw new ArgumentOutOfRangeException(nameof(reorderThreshold), "Reorder threshold cannot be negative.");
        _reorderThreshold = reorderThreshold;
    }

    public int GetStockLevel(string sku)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        return _warehouseStock.Values.Sum(w => w.TryGetValue(sku, out var qty) ? qty : 0);
    }

    public int GetStockLevel(string sku, string warehouse)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentException.ThrowIfNullOrWhiteSpace(warehouse);
        return _warehouseStock.TryGetValue(warehouse, out var stock) && stock.TryGetValue(sku, out var qty) ? qty : 0;
    }

    public void AddStock(string sku, int quantity) => AddStock(sku, quantity, DefaultWarehouse);

    public void AddStock(string sku, int quantity, string warehouse)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentException.ThrowIfNullOrWhiteSpace(warehouse);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be positive.");

        if (!_warehouseStock.ContainsKey(warehouse))
            _warehouseStock[warehouse] = new Dictionary<string, int>();

        _warehouseStock[warehouse].TryGetValue(sku, out var current);
        _warehouseStock[warehouse][sku] = current + quantity;
    }

    public void RemoveStock(string sku, int quantity) => RemoveStock(sku, quantity, DefaultWarehouse);

    public void RemoveStock(string sku, int quantity, string warehouse)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentException.ThrowIfNullOrWhiteSpace(warehouse);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be positive.");

        var current = GetStockLevel(sku, warehouse);
        if (quantity > current)
            throw new InvalidOperationException($"Insufficient stock for '{sku}' in warehouse '{warehouse}'. Available: {current}, requested: {quantity}.");

        _warehouseStock[warehouse][sku] = current - quantity;
    }

    public bool NeedsReorder(string sku)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        return GetStockLevel(sku) <= _reorderThreshold;
    }

    public void TransferStock(string sku, int quantity, string fromWarehouse, string toWarehouse)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentException.ThrowIfNullOrWhiteSpace(fromWarehouse);
        ArgumentException.ThrowIfNullOrWhiteSpace(toWarehouse);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity), "Quantity must be positive.");
        if (fromWarehouse == toWarehouse)
            throw new ArgumentException("Source and destination warehouses must be different.");

        RemoveStock(sku, quantity, fromWarehouse);
        AddStock(sku, quantity, toWarehouse);
    }
}

