+using Microsoft.VisualStudio.TestTools.UnitTesting;
+
+namespace Warehouse.Tests;
+
+[TestClass]
+public class InventoryTrackerTests
+{
+    private InventoryTracker _tracker = null!;
+
+    [TestInitialize]
+    public void Setup()
+    {
+        _tracker = new InventoryTracker(reorderThreshold: 10);
+    }
+
+    // ──────────────────────────────────────────────
+    //  Construction
+    // ──────────────────────────────────────────────
+
+    [TestMethod]
+    public void Constructor_DefaultThreshold_DoesNotThrow()
+    {
+        var tracker = new InventoryTracker();
+        Assert.IsNotNull(tracker);
+    }
+
+    [TestMethod]
+    public void Constructor_NegativeThreshold_Throws()
+    {
+        Assert.ThrowsException<ArgumentOutOfRangeException>(
+            () => new InventoryTracker(reorderThreshold: -1));
+    }
+
+    // ──────────────────────────────────────────────
+    //  AddStock
+    // ──────────────────────────────────────────────
+
+    [TestMethod]
+    public void AddStock_NewSku_SetsLevel()
+    {
+        _tracker.AddStock("SKU-001", 50);
+        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-001"));
+    }
+
+    [TestMethod]
+    public void AddStock_ExistingSku_AccumulatesQuantity()
+    {
+        _tracker.AddStock("SKU-001", 30);
+        _tracker.AddStock("SKU-001", 20);
+        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-001"));
+    }
+
+    [TestMethod]
+    public void AddStock_ZeroQuantity_Throws()
+    {
+        Assert.ThrowsException<ArgumentOutOfRangeException>(
+            () => _tracker.AddStock("SKU-001", 0));
+    }
+
+    [TestMethod]
+    public void AddStock_NegativeQuantity_Throws()
+    {
+        Assert.ThrowsException<ArgumentOutOfRangeException>(
+            () => _tracker.AddStock("SKU-001", -5));
+    }
+
+    [TestMethod]
+    public void AddStock_NullSku_Throws()
+    {
+        Assert.ThrowsException<ArgumentException>(
+            () => _tracker.AddStock(null!, 10));
+    }
+
+    [TestMethod]
+    public void AddStock_EmptySku_Throws()
+    {
+        Assert.ThrowsException<ArgumentException>(
+            () => _tracker.AddStock("", 10));
+    }
+
+    [TestMethod]
+    public void AddStock_ToSpecificWarehouse_TracksPerWarehouse()
+    {
+        _tracker.AddStock("SKU-001", 30, "East");
+        _tracker.AddStock("SKU-001", 20, "West");
+
+        Assert.AreEqual(30, _tracker.GetStockLevel("SKU-001", "East"));
+        Assert.AreEqual(20, _tracker.GetStockLevel("SKU-001", "West"));
+        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-001"));
+    }
+
+    // ──────────────────────────────────────────────
+    //  GetStockLevel
+    // ──────────────────────────────────────────────
+
+    [TestMethod]
+    public void GetStockLevel_UnknownSku_ReturnsZero()
+    {
+        Assert.AreEqual(0, _tracker.GetStockLevel("NONEXISTENT"));
+    }
+
+    [TestMethod]
+    public void GetStockLevel_UnknownWarehouse_ReturnsZero()
+    {
+        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-001", "NoSuchWarehouse"));
+    }
+
+    [TestMethod]
+    public void GetStockLevel_NullSku_Throws()
+    {
+        Assert.ThrowsException<ArgumentException>(
+            () => _tracker.GetStockLevel(null!));
+    }
+
+    [TestMethod]
+    public void GetStockLevel_AggregatesAcrossWarehouses()
+    {
+        _tracker.AddStock("SKU-001", 10, "A");
+        _tracker.AddStock("SKU-001", 20, "B");
+        _tracker.AddStock("SKU-001", 30, "C");
+
+        Assert.AreEqual(60, _tracker.GetStockLevel("SKU-001"));
+    }
+
+    // ──────────────────────────────────────────────
+    //  RemoveStock
+    // ──────────────────────────────────────────────
+
+    [TestMethod]
+    public void RemoveStock_ValidQuantity_DecreasesLevel()
+    {
+        _tracker.AddStock("SKU-001", 50);
+        _tracker.RemoveStock("SKU-001", 20);
+        Assert.AreEqual(30, _tracker.GetStockLevel("SKU-001"));
+    }
+
+    [TestMethod]
+    public void RemoveStock_EntireStock_LeavesZero()
+    {
+        _tracker.AddStock("SKU-001", 25);
+        _tracker.RemoveStock("SKU-001", 25);
+        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-001"));
+    }
+
+    [TestMethod]
+    public void RemoveStock_ExceedsAvailable_Throws()
+    {
+        _tracker.AddStock("SKU-001", 10);
+        Assert.ThrowsException<InvalidOperationException>(
+            () => _tracker.RemoveStock("SKU-001", 11));
+    }
+
+    [TestMethod]
+    public void RemoveStock_ZeroQuantity_Throws()
+    {
+        Assert.ThrowsException<ArgumentOutOfRangeException>(
+            () => _tracker.RemoveStock("SKU-001", 0));
+    }
+
+    [TestMethod]
+    public void RemoveStock_NullSku_Throws()
+    {
+        Assert.ThrowsException<ArgumentException>(
+            () => _tracker.RemoveStock(null!, 5));
+    }
+
+    [TestMethod]
+    public void RemoveStock_FromSpecificWarehouse_OnlyAffectsThatWarehouse()
+    {
+        _tracker.AddStock("SKU-001", 30, "East");
+        _tracker.AddStock("SKU-001", 20, "West");
+
+        _tracker.RemoveStock("SKU-001", 10, "East");
+
+        Assert.AreEqual(20, _tracker.GetStockLevel("SKU-001", "East"));
+        Assert.AreEqual(20, _tracker.GetStockLevel("SKU-001", "West"));
+    }
+
+    // ──────────────────────────────────────────────
+    //  NeedsReorder
+    // ──────────────────────────────────────────────
+
+    [TestMethod]
+    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
+    {
+        _tracker.AddStock("SKU-001", 5);
+        Assert.IsTrue(_tracker.NeedsReorder("SKU-001"));
+    }
+
+    [TestMethod]
+    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
+    {
+        _tracker.AddStock("SKU-001", 10);
+        Assert.IsTrue(_tracker.NeedsReorder("SKU-001"));
+    }
+
+    [TestMethod]
+    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
+    {
+        _tracker.AddStock("SKU-001", 11);
+        Assert.IsFalse(_tracker.NeedsReorder("SKU-001"));
+    }
+
+    [TestMethod]
+    public void NeedsReorder_UnknownSku_ReturnsTrue()
+    {
+        Assert.IsTrue(_tracker.NeedsReorder("GHOST"));
+    }
+
+    [TestMethod]
+    public void NeedsReorder_NullSku_Throws()
+    {
+        Assert.ThrowsException<ArgumentException>(
+            () => _tracker.NeedsReorder(null!));
+    }
+
+    [TestMethod]
+    public void NeedsReorder_StockDropsBelowThresholdAfterRemoval_ReturnsTrue()
+    {
+        _tracker.AddStock("SKU-001", 20);
+        Assert.IsFalse(_tracker.NeedsReorder("SKU-001"));
+
+        _tracker.RemoveStock("SKU-001", 15);
+        Assert.IsTrue(_tracker.NeedsReorder("SKU-001"));
+    }
+
+    [TestMethod]
+    public void NeedsReorder_CustomThreshold_UsesCorrectValue()
+    {
+        var tracker = new InventoryTracker(reorderThreshold: 100);
+        tracker.AddStock("SKU-001", 50);
+
+        Assert.IsTrue(tracker.NeedsReorder("SKU-001"));
+    }
+
+    // ──────────────────────────────────────────────
+    //  TransferStock
+    // ──────────────────────────────────────────────
+
+    [TestMethod]
+    public void TransferStock_ValidTransfer_MovesStockBetweenWarehouses()
+    {
+        _tracker.AddStock("SKU-001", 100, "East");
+        _tracker.TransferStock("SKU-001", 40, "East", "West");
+
+        Assert.AreEqual(60, _tracker.GetStockLevel("SKU-001", "East"));
+        Assert.AreEqual(40, _tracker.GetStockLevel("SKU-001", "West"));
+    }
+
+    [TestMethod]
+    public void TransferStock_PreservesTotalStock()
+    {
+        _tracker.AddStock("SKU-001", 100, "East");
+        var totalBefore = _tracker.GetStockLevel("SKU-001");
+
+        _tracker.TransferStock("SKU-001", 40, "East", "West");
+
+        Assert.AreEqual(totalBefore, _tracker.GetStockLevel("SKU-001"));
+    }
+
+    [TestMethod]
+    public void TransferStock_EntireStock_EmptiesSource()
+    {
+        _tracker.AddStock("SKU-001", 50, "East");
+        _tracker.TransferStock("SKU-001", 50, "East", "West");
+
+        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-001", "East"));
+        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-001", "West"));
+    }
+
+    [TestMethod]
+    public void TransferStock_InsufficientStock_Throws()
+    {
+        _tracker.AddStock("SKU-001", 10, "East");
+
+        Assert.ThrowsException<InvalidOperationException>(
+            () => _tracker.TransferStock("SKU-001", 20, "East", "West"));
+    }
+
+    [TestMethod]
+    public void TransferStock_SameWarehouse_Throws()
+    {
+        _tracker.AddStock("SKU-001", 50, "East");
+
+        Assert.ThrowsException<ArgumentException>(
+            () => _tracker.TransferStock("SKU-001", 10, "East", "East"));
+    }
+
+    [TestMethod]
+    public void TransferStock_ZeroQuantity_Throws()
+    {
+        _tracker.AddStock("SKU-001", 50, "East");
+
+        Assert.ThrowsException<ArgumentOutOfRangeException>(
+            () => _tracker.TransferStock("SKU-001", 0, "East", "West"));
+    }
+
+    [TestMethod]
+    public void TransferStock_NullSku_Throws()
+    {
+        Assert.ThrowsException<ArgumentException>(
+            () => _tracker.TransferStock(null!, 10, "East", "West"));
+    }
+
+    [TestMethod]
+    public void TransferStock_NullSourceWarehouse_Throws()
+    {
+        Assert.ThrowsException<ArgumentException>(
+            () => _tracker.TransferStock("SKU-001", 10, null!, "West"));
+    }
+
+    [TestMethod]
+    public void TransferStock_NullDestWarehouse_Throws()
+    {
+        Assert.ThrowsException<ArgumentException>(
+            () => _tracker.TransferStock("SKU-001", 10, "East", null!));
+    }
+
+    // ──────────────────────────────────────────────
+    //  Multi-SKU isolation
+    // ──────────────────────────────────────────────
+
+    [TestMethod]
+    public void MultipleSkus_TrackedIndependently()
+    {
+        _tracker.AddStock("A", 100);
+        _tracker.AddStock("B", 200);
+
+        _tracker.RemoveStock("A", 50);
+
+        Assert.AreEqual(50, _tracker.GetStockLevel("A"));
+        Assert.AreEqual(200, _tracker.GetStockLevel("B"));
+    }
+}
+

